 private boolean sideBySide(){return getWidth()>=dp(expanded?760:320)&&(!store.prefs.getBoolean("ten_full_start",false)||store.prefs.getBoolean("ten_start_apps",false));}
 private int appColumnWidth(){return getWidth()>=dp(620)?dp(220):Math.min(dp(170),Math.max(dp(120),Math.round((getWidth()-dp(48))*.40f)));}
