 private List<StartSearch.Result> builtins(){List<StartSearch.Result> result=new ArrayList<>();for(String[] b:new String[][]{{"@events","Event Viewer","notes"},{"@devices","Device Manager","computer"},{"@management","Computer Management","computer"},{"@powershell","Nth PowerShell","run"},{"@run","Run","run"},{"@nota","Nth Nota","notes"},{"@files","File Explorer","files"},{"@settings","Settings","control"},{"@browser",BrowserPanel.NAME,"browser"},{"@notes","Notepad","notes"},{"@sticky","Sticky Notes","notes"},{"@gadget:calculator","Calculator","calculator"},{"@calendar","Calendar","calendar"},{"@weather","Weather","weather"},{"@battery","Battery","power"},{"@news","News and interests","feeds"},{"@photos","Photos","pictures-app"},{MediaLibrary.PLAYER,"Nth Media Player","mediaplayer"},{"@taskmanager","Task Manager","taskmanager"},{"@recycle","Recycle Bin","recycle"}})result.add(new StartSearch.Result(b[0],b[1],"Nth tools",b[2],null,true));return result;}
