 private void groupDialog(String old){EditText input=new EditText(getContext());input.setSingleLine();input.setFilters(new InputFilter[]{new InputFilter.LengthFilter(40)});input.setText(old==null?"":old);input.setContentDescription("Tile group name");android.app.AlertDialog dialog=Aero.dialog(getContext()).setTitle(old==null?"New tile group":"Name group").setView(input).setPositiveButton("Save",null).setNegativeButton("Cancel",null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{if(old==null?data.add(input.getText().toString()):data.rename(old,input.getText().toString())){dialog.dismiss();renderTiles();}else input.setError("Choose a unique name (1–40 characters)");}));dialog.show();}
 private static final class TileDrag{final String id;TileDrag(String id){this.id=id;}}
 private void tileOptions(View tile,StartSearch.Result item){PopupMenu m=new PopupMenu(getContext(),tile);m.getMenu().add("Unpin from Start").setOnMenuItemClickListener(v->{List<String> p=new ArrayList<>(store.startPins());p.remove(item.id);store.startPins(p);renderTiles();return true;});SubMenu resize=m.getMenu().addSubMenu("Resize");for(String size:TenTileLayout.SIZES)resize.add(size).setOnMenuItemClickListener(v->{store.prefs.edit().putString("ten_size_"+item.id,size).apply();renderTiles();return true;});SubMenu move=m.getMenu().addSubMenu("Move to group");for(String group:data.groups())move.add(group).setOnMenuItemClickListener(v->{store.prefs.edit().putString("ten_group_"+item.id,group).apply();renderTiles();return true;});for(int delta:new int[]{-1,1})m.getMenu().add(delta<0?"Move earlier":"Move later").setOnMenuItemClickListener(v->{data.reorder(item.id,delta);renderTiles();return true;});m.getMenu().add("More options").setOnMenuItemClickListener(v->{actions.options(tile,item.id);return true;});m.show();}
 void show(boolean keyboard){setVisibility(VISIBLE);bringToFront();searchMode=keyboard;searchFilter="All";showApps=keyboard||store.prefs.getBoolean("ten_start_apps",false);expanded=false;search.setText("");renderRail();refresh();fit();handler.removeCallbacks(live);handler.postDelayed(live,60000-System.currentTimeMillis()%60000);if(keyboard){search.clearFocus();requestFocus();}else requestFocus();}

 void hide(){handler.removeCallbacks(live);((InputMethodManager)getContext().getSystemService(Context.INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(getWindowToken(),0);search.clearFocus();setVisibility(GONE);}
 @Override protected void onDetachedFromWindow(){handler.removeCallbacksAndMessages(null);super.onDetachedFromWindow();}
 JSONObject state(){JSONObject r=new JSONObject();GadgetLayout.put(r,"visible",getVisibility()==VISIBLE);GadgetLayout.put(r,"query",search.getText().toString());GadgetLayout.put(r,"apps",showApps);return r;}
 void restore(JSONObject s){if(s==null||!s.optBoolean("visible"))return;show(false);showApps=s.optBoolean("apps");search.setText(s.optString("query"));fit();}
